        } catch (RuntimeException error) {
            auditSink.recordFallback(flagKey, String.valueOf(defaultValue), context, error);
            return defaultValue;
        }
    }

    private long elapsedMillis(long startNanos) {
        return (System.nanoTime() - startNanos) / 1_000_000;
    }
