public final class InMemoryFeatureFlagProvider implements FeatureFlagProvider {

    private final Map<String, Object> flags = new ConcurrentHashMap<>();

    public InMemoryFeatureFlagProvider(Map<String, Object> initialFlags) {
        flags.putAll(initialFlags);
    }

    public void set(String key, Object value) {
        flags.put(key, value);
    }

    @Override
    public boolean booleanValue(
            String flagKey,
            FeatureFlagEvaluationContext context,
            boolean defaultValue
    ) {
        Object value = flags.get(flagKey);

        if (value instanceof Boolean booleanValue) {
            return booleanValue;
        }

        return defaultValue;
    }

    @Override
    public String stringValue(
            String flagKey,
            FeatureFlagEvaluationContext context,
            String defaultValue
    ) {
        Object value = flags.get(flagKey);

        if (value instanceof String stringValue) {
            return stringValue;
        }

        return defaultValue;
    }

    @Override
    public int intValue(
            String flagKey,
            FeatureFlagEvaluationContext context,
            int defaultValue
    ) {
        Object value = flags.get(flagKey);

        if (value instanceof Integer intValue) {
            return intValue;
        }

        return defaultValue;
    }

    @Override
    public double doubleValue(
            String flagKey,
            FeatureFlagEvaluationContext context,
            double defaultValue
    ) {
        Object value = flags.get(flagKey);

        if (value instanceof Double doubleValue) {
            return doubleValue;
        }

        if (value instanceof Integer intValue) {
            return intValue.doubleValue();
        }

        return defaultValue;
    }

    @Override
    public <T> T objectValue(
            String flagKey,
            FeatureFlagEvaluationContext context,
            T defaultValue,
            Class<T> type
    ) {
        Object value = flags.get(flagKey);

        if (type.isInstance(value)) {
            return type.cast(value);
        }

        return defaultValue;
    }
