    }

    @Override
    public int intValue(
            String flagKey,
            FeatureFlagEvaluationContext context,
            int defaultValue
    ) {
        Object value = values.get(flagKey);
        return value instanceof Integer intValue ? intValue : defaultValue;
    }

    @Override
    public double doubleValue(
            String flagKey,
            FeatureFlagEvaluationContext context,
            double defaultValue
    ) {
        Object value = values.get(flagKey);
