    private static final ThreadLocal<SqlSession> CURRENT = new ThreadLocal<>();

    public boolean hasCurrent() {
        return CURRENT.get() != null;
    }

    public void bind(SqlSession session) {
        CURRENT.set(session);
    }

    public SqlSession current() {
