", _jsx(_components.pre, {
      children: _jsx(_components.code, {
        className: "language-java",
        children: "public final class MyBatisTransactionManager implements TransactionManager {

    private final SqlSessionFactory sqlSessionFactory;
    private final SqlSessionHolder holder;

    @Inject
    public MyBatisTransactionManager(
            SqlSessionFactory sqlSessionFactory,
            SqlSessionHolder holder
    ) {
        this.sqlSessionFactory = sqlSessionFactory;
        this.holder = holder;
    }

    @Override
    public <T> T executeInTransaction(CheckedSupplier<T> supplier) throws Exception {
        if (holder.hasCurrent()) {
            return supplier.get();
        }

        try (SqlSession session = sqlSessionFactory.openSession(false)) {
            holder.bind(session);

            try {
                T result = supplier.get();
                session.commit();
                return result;
            } catch (Exception | RuntimeException error) {
                session.rollback();
                throw error;
            } finally {
                holder.clear();
            }
        }
    }
}
